class Solution:
    def maxWeight(self, weights: List[int], capacity1: int, capacity2: int) -> int:
        reachable = {(0, 0)}
        for w in weights:
            nxt = set(reachable)
            for w1, w2 in reachable:
                if w1 + w <= capacity1:
                    nxt.add((w1 + w, w2))
                if w2 + w <= capacity2:
                    nxt.add((w1, w2 + w))
