#include <vector>
#include <algorithm>

class Solution {
public:
    int maxWeight(std::vector<int>& weights, int capacity1, int capacity2) {
        std::vector<std::vector<bool>> dp(capacity1 + 1, std::vector<bool>(capacity2 + 1, false));
        dp[0][0] = true;

        for (int w : weights) {
            for (int w1 = capacity1; w1 >= 0; --w1) {
                for (int w2 = capacity2; w2 >= 0; --w2) {
                    if (w1 >= w && dp[w1 - w][w2]) dp[w1][w2] = true;
                    if (w2 >= w && dp[w1][w2 - w]) dp[w1][w2] = true;
                }
            }
        }

        int ans = 0;
        for (int w1 = 0; w1 <= capacity1; ++w1) {
            for (int w2 = 0; w2 <= capacity2; ++w2) {
                if (dp[w1][w2]) {
                    ans = std::max(ans, w1 + w2);
                }
            }
        }
        return ans;
    }
};

class Solution {
    public int maxWeight(int[] weights, int capacity1, int capacity2) {
        boolean[][] dp = new boolean[capacity1 + 1][capacity2 + 1];
        dp[0][0] = true;

        for (int w : weights) {
            for (int w1 = capacity1; w1 >= 0; w1--) {
                for (int w2 = capacity2; w2 >= 0; w2--) {
                    if (w1 >= w && dp[w1 - w][w2]) dp[w1][w2] = true;
                    if (w2 >= w && dp[w1][w2 - w]) dp[w1][w2] = true;
                }
            }
        }

        int ans = 0;
        for (int w1 = 0; w1 <= capacity1; w1++) {
            for (int w2 = 0; w2 <= capacity2; w2++) {
                if (dp[w1][w2]) {
                    ans = Math.max(ans, w1 + w2);
                }
            }
        }
        return ans;
    }
}

